import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { basename, dirname, join, relative } from "node:path";

/** First line of every generated file: how a generated file whose source is gone is recognized. */
export const GENERATED_HEADER = "// Generated by @spacexr/3d-tiles-babylon-tools.";

const STAGE_SUFFIXES: Readonly<Record<string, string>> = { vertex: "VertexShader", fragment: "PixelShader", compute: "ComputeShader" };

/**
 * How a shader file is used, from where it lies:
 *
 * - `stage`: a whole shader, `name.vertex.glsl`, `name.fragment.glsl` or `name.compute.glsl`, registered in `ShadersStore`;
 * - `include`: under an `includes` folder, registered in `IncludesShadersStore` for `#include<name>`;
 * - `snippet`: under a `snippets` folder, code a material plugin injects, exported and not registered.
 */
export type ShaderKind = "stage" | "include" | "snippet";

/** The TypeScript module generated from a shader file. */
export interface IGeneratedShader {
    /** Path of the shader file. */
    source: string;
    /** Path of the generated module, beside the shader file. */
    target: string;
    kind: ShaderKind;
    /** Key in the Babylon.js shader store. */
    name: string;
    /** Name of the exported constant: the key, followed by `WGSL` for a WGSL file, as in Babylon.js. */
    exportName: string;
    /** Content of the generated module. */
    content: string;
}

/** What a build found. Paths are relative to the root it was given. */
export interface IShaderBuildReport {
    /** Generated modules up to date. */
    unchanged: string[];
    /** Generated modules that differ from their shader file: written, unless checking. */
    changed: string[];
    /** Generated modules whose shader file is gone: never deleted, the build only reports them. */
    orphans: string[];
}

export interface IBuildShadersOptions {
    /** Writes nothing, and only reports what a build would change. */
    check?: boolean;
}

/**
 * Removes comments, indentation and blank lines. Lines are never joined: a preprocessor directive must start its line,
 * and the code stays readable in a shader compilation error.
 */
export function stripShader(source: string): string {
    const text = (source.charCodeAt(0) === 0xfeff ? source.slice(1) : source)
        .replace(/\r\n?/g, "\n")
        .replace(/\/\*[\s\S]*?\*\//g, "")
        .replace(/\/\/.*$/gm, "");
    return text
        .split("\n")
        .map((line) => line.trim())
        .filter((line) => line.length > 0)
        .join("\n");
}

/** The kind and the exported name of a shader file. */
export function describeShader(path: string): { kind: ShaderKind; name: string } {
    const folders = dirname(path).split(/[\\/]/);
    const [base, stage, ...rest] = basename(path).split(".").slice(0, -1);
    const placed: ShaderKind | undefined = folders.includes("includes") ? "include" : folders.includes("snippets") ? "snippet" : undefined;
    const suffix = placed ? "" : STAGE_SUFFIXES[stage ?? ""];
    const expectedParts = placed ? stage === undefined : suffix !== undefined;
    if (!base || rest.length > 0 || !expectedParts) {
        throw new Error(`${path}: expected name.vertex, name.fragment or name.compute, or a plain name under includes or snippets.`);
    }
    const name = `${base}${suffix ?? ""}`;
    if (!/^[A-Za-z_$][\w$]*$/.test(name)) throw new Error(`${path}: ${name} is not a valid TypeScript name.`);
    return { kind: placed ?? "stage", name };
}

/** Generates the TypeScript module of a shader file. */
export function generateShader(path: string): IGeneratedShader {
    const { kind, name } = describeShader(path);
    const wgsl = path.endsWith(".wgsl");
    const body = stripShader(readFileSync(path, "utf8")).replace(/[\\`]/g, "\\$&").replace(/\$\{/g, "\\${");
    const store = `${kind === "include" ? "IncludesShadersStore" : "ShadersStore"}${wgsl ? "WGSL" : ""}`;
    const exportName = `${name}${wgsl ? "WGSL" : ""}`;
    const lines = [
        `${GENERATED_HEADER} Edit ${basename(path)}, then run \`npm run shaders\`.`,
        ...(kind === "snippet" ? [] : ['import { ShaderStore } from "@babylonjs/core/Engines/shaderStore.js";', ""]),
        `const name = "${name}";`,
        `const shader = \`${body}\`;`,
        ...(kind === "snippet" ? [] : [`ShaderStore.${store}[name] = shader;`]),
        "/** @internal */",
        `export const ${exportName} = { name, shader };`,
        "",
    ];
    return { source: path, target: path.replace(/\.(glsl|wgsl)$/, ".ts"), kind, name, exportName, content: lines.join("\n") };
}

function listFiles(root: string): string[] {
    return (readdirSync(root, { recursive: true, encoding: "utf8" }) as string[]).map((file) => join(root, file)).sort();
}

/**
 * Generates a TypeScript module beside every `.glsl` and `.wgsl` file under a folder.
 *
 * @throws Error When a shader file does not follow the naming rules, or two files would generate the same module.
 */
export function buildShaders(root: string, options: IBuildShadersOptions = {}): IShaderBuildReport {
    const files = listFiles(root);
    const report: IShaderBuildReport = { unchanged: [], changed: [], orphans: [] };
    const targets = new Set<string>();
    for (const file of files.filter((path) => /\.(glsl|wgsl)$/.test(path))) {
        const generated = generateShader(file);
        if (targets.has(generated.target)) throw new Error(`${file}: another shader file generates ${generated.target}.`);
        targets.add(generated.target);
        const current = existsSync(generated.target) ? readFileSync(generated.target, "utf8").replace(/\r\n/g, "\n") : undefined;
        const label = relative(root, generated.target);
        if (current === generated.content) {
            report.unchanged.push(label);
            continue;
        }
        report.changed.push(label);
        if (!options.check) writeFileSync(generated.target, generated.content);
    }
    for (const file of files.filter((path) => path.endsWith(".ts") && !targets.has(path))) {
        if (readFileSync(file, "utf8").startsWith(GENERATED_HEADER)) report.orphans.push(relative(root, file));
    }
    return report;
}
